/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_31_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_32_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_33_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_39_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_40_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_41_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_47_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_48_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_49_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_55_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_56_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_57_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "img_68", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'HWP'); } }, { id: "txt_text69", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'HWP'); } }, { id: "img_71", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLS' || (dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLSX'); } }, { id: "txt_text72", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLS' || (dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLSX'); } }, { id: "img_74", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'DOC'); } }, { id: "txt_text75", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'DOC'); } }, { id: "img_77", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PPT'); } }, { id: "txt_text78", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PPT'); } }, { id: "img_80", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PDF'); } }, { id: "txt_text81", fn: function(){ return ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_82", fn: function(){ return (!(((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'HWP') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLS' || (dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'XLSX') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'DOC') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PPT') || ((dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attachAdm.fileSurFix"); })()) === 'PDF'))); } }, { id: "c_when_94", fn: function(){ return ((dma_comSprtSvcApplVO.get("applPersLmtYn") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.applPersLmtYn"); })()) === 'Y'); } }, { id: "tr_96", fn: function(){ return ((dma_comSprtSvcApplVO.get("applPersLmtYn") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.applPersLmtYn"); })()) === 'Y'); } }, { id: "c_otherwise_108", fn: function(){ return (!(((dma_comSprtSvcApplVO.get("applPersLmtYn") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.applPersLmtYn"); })()) === 'Y'))); } }, { id: "if_contactChrgDesignYn", fn: function(){ return ((dma_comSprtSvcApplVO.get("contactChrgDesignYn") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.contactChrgDesignYn"); })()) === 'Y'); } }, { id: "tr_123", fn: function(){ return ((dma_comSprtSvcApplVO.get("contactChrgDesignYn") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.contactChrgDesignYn"); })()) === 'Y'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_64", entity: "dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO", countIds: [], cells: [{ childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc6", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc9", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc10", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.util.getComponent('btnUpdate').setStyle("display", "none");
        $c.util.getComponent('btnDelete').setStyle("display", "none");
        for (let i = 0; i < $("input[name='chrgNm']").length; i++) {
            $("input[name='chrgNm']").eq(i).attr('readonly', true);
            $("input[name='jobtitlNm']").eq(i).attr('readonly', true);
            $("input[name='telNo']").eq(i).attr('readonly', true);
            $("input[name='cellphoneNo']").eq(i).attr('readonly', true);
            $("input[name='email']").eq(i).attr('readonly', true);
        }
        scwin.perInfo1.setStyle("display", "none");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16606.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description btnUpdate 을(를) 보이기를 바꾼다 · btnDelete 을(를) 보이기를 바꾼다 · perInfo1 을(를) 보이기를 바꾼다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16606.onpageload' });
    }
};


