/**
 * @method
 * @name scwin.tx_fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        target: "dlt_comSprtSvcApplVOComSprtSvcAdmAttachVO=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16606.tx_fnSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

