*/
scwin.tx_fnFileDown = async function () {
    try { return await $c.data.downFile("/support/comSprtSvcFileDownload.do", "", ($c.util.getComponent("dma_fnFileDownReq") ? $c.util.getComponent("dma_fnFileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fnApplPersCntChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnApplPersCntChk = async function () {
    const sbmOptions = {
        id: "tx_fnApplPersCntChk",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnApplPersCntChkReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16606.tx_fnApplPersCntChk" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


