 * @hidden N
*/
scwin.fnApplPersCntChk_done = function (data) {
    /* sdd-asis-lifecycle:begin fnApplPersCntChk_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    pCnt = scwin.result.returnVal;
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.fnApplPersCntChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnApplPersCntChk = async function () {
    const r = await scwin.tx_fnApplPersCntChk();
    try {
        scwin.fnApplPersCntChk_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil16606.fnApplPersCntChk' });
    }
    return r;
};
